// Интерфейс
(function(){
const N=NFM; const $=s=>document.querySelector(s); const V=()=>$('#view');
let S=null; const st={stack:[],cur:null,arg:null,sel:null,tab:{},m:null};
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const T=c=>S.T[c]; const tf=c=>`<span class="flag">${T(c).f}</span>`; const tn=c=>T(c).f+' '+T(c).n;
const posB=p=>`<span class="pos p${N.POS[p.pos][1]}">${N.POS[p.pos][0]}</span>`;
const rtC=r=>r>=8.5?'r9':r>=7.5?'r8':r>=6.8?'r7':r>=6.2?'r6':r>=5.5?'r5':'r4';
const rtB=r=>`<span class="rt ${rtC(r)}">${(+r).toFixed(1)}</span>`;
const stars=t=>`<span class="stars">${N.starsHtml(N.stars(t))}</span>`;
const avgR=p=>p.rh&&p.rh.length?(p.rh.reduce((s,x)=>s+x[1],0)/p.rh.length):null;
const short=p=>{const a=p.n.split(' ');return a.length>1?a[0][0]+'. '+a.slice(1).join(' '):p.n};
const PREF=JSON.parse(localStorage.getItem('nfm_pref')||'{"spd":1}');
const savePref=()=>localStorage.setItem('nfm_pref',JSON.stringify(PREF));
function toast(t){const e=$('#toast');e.innerHTML=t;e.classList.add('on');clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('on'),2600)}
function modal(html){const m=$('#modal');m.querySelector('.mbox').innerHTML=html;m.classList.remove('hidden');}
function closeM(){$('#modal').classList.add('hidden')}
$('#modal').addEventListener('click',e=>{if(e.target.id==='modal'&&!st.lockM)closeM()});
function top(title,back=true){ $('#top').innerHTML=(back?`<button class="back" onclick="UI.back()">‹</button>`:'')+`<div class="ttl">${title}</div>`+(S?`<div class="dt">${N.fmtD(S.d)}<br>${tf(S.me)} ${esc(T(S.me).n)}</div>`:''); }
function go(name,arg,noPush){ if(st.cur&&!noPush&&st.cur!=='match'&&st.cur!=='post')st.stack.push([st.cur,st.arg]); st.cur=name; st.arg=arg; st.sel=null; const v=V(); v.style.animation='none'; void v.offsetWidth; v.style.animation=''; SCR[name](arg); window.scrollTo(0,0); }
function back(){ const p=st.stack.pop(); if(!p)return go('hub',null,true); go(p[0],p[1],true); }
function home(){ st.stack=[]; go('hub',null,true); }
const meta=()=>JSON.parse(localStorage.getItem('nfm_meta')||'{}');
function save(slot){ slot=slot||S.slot||1; S.slot=slot; try{ localStorage.setItem('nfm_s'+slot,N.serialize(S)); const m=meta(); m[slot]={t:S.me,d:S.d,c:S.coach,ts:Date.now()}; localStorage.setItem('nfm_meta',JSON.stringify(m)); return true;}catch(e){ toast('⚠️ Не удалось сохранить: '+e.message); return false;} }
function load(slot){ const s=localStorage.getItem('nfm_s'+slot); if(!s)return false; const L=N.deserialize(s); oldCheck(L); S=L; S.slot=slot; N.setS(S); fixFlags(); return true; }
function oldCheck(L){ if(!L||(L.v||1)<3) throw new Error('это сохранение старой версии игры (v'+((L&&L.v)||1)+'). В версии 3 переработаны турниры (стыки, двухматчевые раунды, Лиги наций с повышением и вылетом), имена и данные игроков — старые сохранения несовместимы. Пожалуйста, начните новую игру.'); }
function fixFlags(){ for(const t of N.TEAMS) if(S.T[t.c]) S.T[t.c].f=t.f; }
const SCR={};
SCR.title=()=>{ $('#top').innerHTML=''; const m=meta(); const any=Object.keys(m).length;
 V().innerHTML=`<div class="logo"><div class="ball">⚽</div><h1>Национальный<br>Футбольный Менеджер</h1><p>Возглавьте сборную и приведите её к славе</p></div>
 <div class="card"><button class="btn g w big" onclick="UI.go('newgame')">Новая игра</button>
 ${any?`<div style="height:8px"></div><button class="btn w big" onclick="UI.slots()">Загрузить игру</button>`:''}
 <div style="height:8px"></div><button class="btn gh w" onclick="UI.help()">Как играть</button></div>
 <p class="ctr mut sm">210 сборных · 6 конфедераций · отборы, Лиги наций, континентальные первенства и чемпионат мира.<br>Все имена и клубы вымышлены.</p>`; };
function help(){ modal(`<h2>Как играть</h2><p>Вы — главный тренер сборной. Нажимайте <b>«Продолжить»</b>, чтобы двигаться по календарю: международные окна (март, июнь, сентябрь, октябрь, ноябрь), отборочные турниры, Лиги наций, финальные турниры.</p><p><b>Вызов:</b> перед каждым окном выберите 18–23 игрока. <b>Тактика:</b> перетаскивайте или нажимайте игроков на поле, чтобы менять их местами; повторное нажатие — индивидуальная установка.</p><p><b>Матч:</b> следите за событиями, меняйте тактику и делайте замены прямо по ходу игры. Пауза — в любой момент.</p><p><b>Федерация:</b> следите за доверием. Если оно упадёт слишком низко — вас уволят. Успехи приносят бюджет на инфраструктуру и предложения от других сборных.</p><button class="btn w" onclick="UI.closeM()">Понятно</button>`); }
SCR.newgame=()=>{ top('Новая игра'); st.ng=st.ng||{conf:null,name:PREF.coach||''};
 const confs=Object.keys(N.CONFS); const ic={UEFA:'🌍',CONMEBOL:'🌎',CONCACAF:'🌎',CAF:'🌍',AFC:'🌏',OFC:'🌏'};
 if(!st.ng.conf){ V().innerHTML=`<div class="card"><h3>Ваше имя</h3><input type="text" id="cn" placeholder="Имя тренера" value="${esc(st.ng.name)}" oninput="UI.st.ng.name=this.value"></div>
 <div class="card"><h3>Выберите конфедерацию</h3>${confs.map(c=>`<div class="row c" onclick="UI.st.ng.conf='${c}';UI.go('newgame',null,true)"><span class="flag">${ic[c]}</span><div class="f1 b">${N.CONFS[c]}</div><span class="mut">${N.TEAMS.filter(t=>t.conf===c).length} ›</span></div>`).join('')}</div>`; return; }
 const ts=N.TEAMS.filter(t=>t.conf===st.ng.conf).sort((a,b)=>b.r-a.r);
 V().innerHTML=`<div class="card"><div class="row"><div class="f1 b">${N.CONFS[st.ng.conf]}</div><button class="btn sm" onclick="UI.st.ng.conf=null;UI.go('newgame',null,true)">Сменить</button></div>
 ${ts.map(t=>`<div class="row c" onclick="UI.pickTeam('${t.c}')"><span class="flag">${t.f}</span><div class="f1"><div class="b">${t.n}</div><div class="sm mut">Сила ${t.r}</div></div><span class="stars">${N.starsHtml(N.stars(t))}</span></div>`).join('')}</div>`; };
function pickTeam(c){ const t=N.TEAMS.find(x=>x.c===c); const diff=t.r>=84?'Фаворит: ожидаются только победы и трофеи.':t.r>=75?'Сильная сборная: выход в финальные турниры обязателен.':t.r>=64?'Середняк: каждое попадание в финальный турнир — успех.':'Аутсайдер: давления мало, каждая победа — праздник.';
 const m=meta(); const free=[1,2,3].find(i=>!m[i])||1;
 modal(`<div class="ctr"><div style="font-size:64px">${t.f}</div><h2 style="margin:4px 0">${t.n}</h2><div class="stars" style="font-size:22px">${N.starsHtml(N.stars(t))}</div><p class="mut">${diff}</p></div>
 <h3 class="mut sm">Слот сохранения</h3><div class="tabs">${[1,2,3].map(i=>`<div class="tab ${i===free?'on':''}" id="sl${i}" onclick="UI.st.slot=${i};document.querySelectorAll('[id^=sl]').forEach(e=>e.classList.remove('on'));this.classList.add('on')">Слот ${i}${m[i]?' (занят)':''}</div>`).join('')}</div>
 <div style="height:10px"></div><button class="btn g w big" onclick="UI.start('${c}')">Возглавить сборную</button><div style="height:6px"></div><button class="btn gh w" onclick="UI.closeM()">Назад</button>`); st.slot=free; }
function start(c){ closeM(); V().innerHTML='<div class="card ctr"><span class="sp"></span> Генерация мира: 210 сборных, ~5000 игроков…</div>';
 setTimeout(()=>{ const name=(st.ng.name||'').trim()||'Тренер'; PREF.coach=name; savePref(); S=N.newGame(c,name); S.slot=st.slot||1; save(); st.ng=null; home(); },30); }
function nextUser(){ return S.F.filter(f=>!f.r&&(f.h===S.me||f.a===S.me)).sort((a,b)=>a.d<b.d?-1:1); }
function cName(f){ const c=S.C[f.c]; return c?c.n:'Матч'; }
function rank(c){ return Object.values(S.T).sort((a,b)=>b.elo-a.elo).findIndex(t=>t.c===c)+1; }
SCR.hub=()=>{ top('Главное меню',false); const me=T(S.me); const nx=nextUser(); const f=nx[0]; const unread=S.u.mail.filter(m=>!m.rd).length;
 let card='<div class="card ctr mut">Ближайших матчей нет. Назначьте товарищеский матч в разделе «Соревнования».</div>';
 if(f){ const home=f.h===S.me; const today=f.d===S.d; const days=N.diffD(S.d,f.d);
  card=`<div class="card nm"><h3>${today?'⚽ Сегодня матч':'Следующий матч'} · ${N.fmtD(f.d)}${today?'':' · через '+days+' дн.'}</h3>
  <div class="vs"><div><div class="flag">${T(f.h).f}</div><div class="tn">${esc(T(f.h).n)}</div>${stars(T(f.h))}</div><div><div class="b" style="font-size:22px">VS</div><div class="sm mut">${f.neu?'нейтральное поле':home?'дома':'в гостях'}</div></div><div><div class="flag">${T(f.a).f}</div><div class="tn">${esc(T(f.a).n)}</div>${stars(T(f.a))}</div></div>
  <div class="ctr sm mut" style="margin-top:6px">${esc(cName(f))} · ${esc(f.st)}</div></div>`; }
 const tl=(i,t,fn,bd)=>`<div class="tile" onclick="${fn}"><span class="i">${i}</span>${t}${bd?`<span class="bd">${bd}</span>`:''}</div>`;
 V().innerHTML=`<div class="card"><div class="row" style="border:0"><span class="flag" style="font-size:40px">${me.f}</span><div class="f1"><div class="b" style="font-size:18px">${esc(me.n)}</div><div class="sm mut">Тренер: ${esc(S.coach)} · ${stars(me)} · Эло ${me.elo} (#${rank(S.me)} в мире)</div></div></div>
 <div class="sm" style="display:flex;justify-content:space-between"><span>Доверие федерации</span><b class="${S.u.trust<25?'red':S.u.trust>70?'grn':''}">${S.u.trust}%</b></div><div class="bar t"><i style="width:${S.u.trust}%"></i></div>
 <div class="sm mut" style="margin-top:6px">Бюджет: <b class="gold">${S.u.bud}</b> · Баланс: ${S.u.stat.w}В ${S.u.stat.d}Н ${S.u.stat.l}П · Вызвано: ${S.u.call.length}</div></div>
 ${card}
 <button class="btn g w big" id="cont" onclick="UI.cont()">▶ Продолжить</button>
 <div style="height:10px"></div>
 <div class="tiles">${tl('👥','Состав / Вызов',"UI.go('squad')")}${tl('🧢','U-21 команда',"UI.go('u21')")}${tl('📋','Тактика',"UI.go('tactics')")}
 ${tl('🏋️','Тренировка',"UI.go('training')")}${tl('🏆','Соревнования',"UI.go('comps')")}${tl('📊','Статистика',"UI.go('stats')")}
 ${tl('🏛️','Федерация',"UI.go('fed')")}${tl('✉️','Почта',"UI.go('mail')",unread||'')}${tl('⚙️','Настройки',"UI.go('settings')")}</div>
 <div class="card"><h3>Календарь сборной</h3>${nx.slice(0,6).map(f=>fixRow(f)).join('')||'<div class="mut sm">Нет запланированных матчей</div>'}</div>
 <div class="card"><h3>Почта</h3>${S.u.mail.slice(0,3).map((m,i)=>`<div class="row c" onclick="UI.openMail(${i})"><span>${m.rd?'📭':'📬'}</span><div class="f1"><div class="${m.rd?'':'b'}">${esc(m.sub)}</div><div class="sm mut">${esc(m.from)} · ${N.fmtD(m.d,1)}</div></div></div>`).join('')}</div>`; };
function fixRow(f,showComp=true){ const r=f.r; const me=f.h===S.me||f.a===S.me; const sc=r?`<b>${r.hg}:${r.ag}</b>${r.pen?`<div class="sm mut">пен ${r.pen.join(':')}</div>`:r.et?'<div class="sm mut">д.в.</div>':''}${r.agg?`<div class="sm mut">сумма ${r.agg[0]}:${r.agg[1]}</div>`:''}`:`<span class="mut sm">${N.fmtD(f.d,1)}</span>`;
 let cls=''; if(r&&me){ const my=f.h===S.me?r.hg:r.ag, op=f.h===S.me?r.ag:r.hg; const w=r.w?(r.w===S.me?1:-1):(my>op?1:my<op?-1:0); cls=w>0?'grn':w<0?'red':'gold'; }
 return `<div class="row ${r&&f.u?'c':''}" ${r&&f.u?`onclick="UI.matchDet(${f.id})"`:''}><div class="f1 right ${f.h===S.me?'b':''}">${esc(T(f.h).n)} ${T(f.h).f}</div><div class="ctr ${cls}" style="min-width:64px">${sc}</div><div class="f1 ${f.a===S.me?'b':''}">${T(f.a).f} ${esc(T(f.a).n)}</div></div>${showComp?`<div class="sm mut ctr" style="margin-top:-4px;padding-bottom:4px">${esc(S.C[f.c]?S.C[f.c].sh:'')} · ${esc(f.st)}${r?' · '+N.fmtD(f.d,1):''}</div>`:''}`; }
function cont(){ if(S.u.fired) return go('fired');
 const uf=N.userFixToday(); if(uf) return go('prematch',uf.id);
 const b=$('#cont'); if(b){b.disabled=true;b.innerHTML='<span class="sp"></span> Симуляция…';}
 setTimeout(()=>{ const r=N.advance(); save(); if(r.stop==='fired') return go('fired');
  const msg={match:'⚽ День матча!',win:'🌍 Международное окно — проверьте вызов',draw:'🎲 Жеребьёвка — новое письмо',year:'🎆 Новый год!',comp:'🏁 Турнир завершён — смотрите почту'}[r.stop]; if(msg)toast(msg);
  home(); },20); }
SCR.mail=()=>{ top('Почта'); V().innerHTML=`<div class="card">${S.u.mail.map((m,i)=>`<div class="row c" onclick="UI.openMail(${i})"><span>${m.act&&!m.act.done?'⭐':m.rd?'📭':'📬'}</span><div class="f1"><div class="${m.rd?'':'b'}">${esc(m.sub)}</div><div class="sm mut">${esc(m.from)} · ${N.fmtD(m.d,1)}</div></div></div>`).join('')||'<div class="mut">Писем нет</div>'}</div>`; };
function openMail(i){ const m=S.u.mail[i]; m.rd=1; let act='';
 if(m.act&&m.act.type==='offer'&&!m.act.done) act=`<button class="btn g w" onclick="UI.acceptJob(${i})">Принять предложение</button><div style="height:6px"></div><button class="btn w" onclick="UI.S().u.mail[${i}].act.done=1;UI.closeM();UI.refresh()">Отказаться</button>`;
 if(m.act&&m.act.type==='fired'&&S.u.fired) act=`<button class="btn g w" onclick="UI.closeM();UI.go('fired')">Выбрать новую сборную</button>`;
 modal(`<div class="sm mut">${esc(m.from)} · ${N.fmtD(m.d)}</div><h2 style="margin:6px 0">${esc(m.sub)}</h2><p style="white-space:pre-wrap">${m.body}</p>${act}<div style="height:6px"></div><button class="btn gh w" onclick="UI.closeM();UI.refresh()">Закрыть</button>`); }
function acceptJob(i){ const m=S.u.mail[i]; m.act.done=1; N.takeJob(m.act.t); save(); closeM(); toast('Вы возглавили '+tn(S.me)); home(); }
SCR.fired=()=>{ top('Вы уволены',false); const m=S.u.mail.find(m=>m.act&&m.act.type==='fired'); const off=m?m.act.off:[];
 V().innerHTML=`<div class="card ctr"><div style="font-size:54px">📉</div><h2>Федерация отправила вас в отставку</h2><p class="mut">Но без работы вы не останетесь. Выберите одно из предложений:</p></div><div class="card">${off.map(c=>`<div class="row c" onclick="UI.takeJ('${c}')">${tf(c)}<div class="f1 b">${esc(T(c).n)}</div>${stars(T(c))}</div>`).join('')}</div>`; };
function takeJ(c){ N.takeJob(c); save(); home(); }
SCR.squad=()=>{ top('Состав / Вызов'); const tab=st.tab.sq||'call'; const pool=N.pool(S.me); const call=new Set(S.u.call);
 const tabs=`<div class="tabs">${[['call','Вызов ('+S.u.call.length+'/23)'],['scout','Найти больше игроков'],['ret','Завершившие']].map(([k,n])=>`<div class="tab ${tab===k?'on':''}" onclick="UI.st.tab.sq='${k}';UI.refresh()">${n}</div>`).join('')}</div>`;
 if(tab==='scout'){ const fd=(S.u.found||[]).map(id=>S.P[id]).filter(Boolean);
  V().innerHTML=tabs+`<div class="card"><h3>Скаутская служба · уровень ${S.u.infra.scout}</h3><p class="sm mut">Скауты ищут игроков с правом выступать за сборную, в том числе с двойным гражданством (🛂). Поисков в этом окне: <b>${S.u.scoutLeft}</b>.</p><button class="btn g w" ${S.u.scoutLeft>0?'':'disabled'} onclick="UI.doScout()">🔎 Найти больше игроков</button></div>
  <div class="card"><h3>Найденные игроки</h3>${fd.map(p=>`<div class="row">${posB(p)}<div class="f1 c" onclick="UI.player(${p.id})"><div class="b">${esc(p.n)}</div><div class="sm mut">${p.age} лет · ${esc(p.club)}${p.dual?' · 🛂 также '+T(p.dual).f+' '+T(p.dual).n:''}</div></div><span class="ovr">${p.o}</span><button class="btn sm g" onclick="UI.invite(${p.id})">Пригласить</button></div>`).join('')||'<div class="mut sm">Пока никого. Запустите поиск.</div>'}</div>`; return; }
 if(tab==='ret'){ const rs=Object.values(S.P).filter(p=>p.t===S.me&&p.ret).sort((a,b)=>b.caps-a.caps); V().innerHTML=tabs+`<div class="card">${rs.map(p=>`<div class="row c" onclick="UI.player(${p.id})">${posB(p)}<div class="f1">${esc(p.n)} <span class="sm mut">завершил в ${p.ret}</span></div><span class="sm">${p.caps} м · ${p.g} г</span></div>`).join('')||'<div class="mut">Пока никто не завершил карьеру</div>'}</div>`; return; }
 const flt=st.tab.sqf||'all';
 const list=pool.filter(p=>flt==='all'||N.POS[p.pos][1]===flt).sort((a,b)=>'GDMF'.indexOf(N.POS[a.pos][1])-'GDMF'.indexOf(N.POS[b.pos][1])||b.o-a.o);
 const cnt=g=>S.u.call.filter(id=>S.P[id]&&N.POS[S.P[id].pos][1]===g).length;
 V().innerHTML=tabs+`<div class="card"><div class="row" style="border:0"><div class="f1">Вызвано: <b class="${S.u.call.length<18||S.u.call.length>23?'red':'grn'}">${S.u.call.length}</b> (нужно 18–23) · ВР ${cnt('G')} · З ${cnt('D')} · П ${cnt('M')} · Н ${cnt('F')}</div><button class="btn sm" onclick="UI.autoCall()">Автовызов</button></div>
 <div class="tabs">${[['all','Все'],['G','ВР'],['D','Защ'],['M','ПЗ'],['F','Нап']].map(([k,n])=>`<div class="tab ${flt===k?'on':''}" onclick="UI.st.tab.sqf='${k}';UI.refresh()">${n}</div>`).join('')}</div></div>
 <div class="card">${list.map(p=>`<div class="row"><input type="checkbox" ${call.has(p.id)?'checked':''} onchange="UI.toggleCall(${p.id},this.checked)" style="width:20px;height:20px">${posB(p)}<div class="f1 c" onclick="UI.player(${p.id})"><div class="b">${esc(p.n)} ${p.inj?'<span class="red">🚑'+p.inj+'д</span>':''}${p.sus?'<span class="red">🟥</span>':''}${p.dual?' 🛂':''}</div><div class="sm mut">${p.age} л · ${esc(p.club)} · ${p.caps} м, ${p.g} г</div></div><div class="ctr sm"><div>Ф ${(+p.form).toFixed(1)}</div><div class="${p.mor<40?'red':p.mor>75?'grn':'mut'}">М ${p.mor}</div></div><span class="ovr">${p.o}</span></div>`).join('')}</div>`; };
function toggleCall(id,on){ const c=S.u.call; if(on){ if(c.length>=23){toast('Максимум 23 игрока');return refresh();} if(!c.includes(id))c.push(id);} else S.u.call=c.filter(x=>x!==id);
 if(S.u.xi){ const x=S.u.xi; x.s=x.s.map(i=>S.u.call.includes(i)?i:null); x.b=S.u.call.filter(i=>!x.s.includes(i)); }
 refresh(); }
function autoCall(){ N.autoCall(); toast('Вызов сформирован'); refresh(); }
function doScout(){ const r=N.scout(); toast(r?'Найдено игроков: '+r.length:'Поиски исчерпаны'); save(); refresh(); }
function invite(id){ const r=N.invite(id); toast(r); save(); refresh(); }
function spark(rh){ if(!rh||rh.length<2) return '<div class="sm mut">Недостаточно матчей для графика</div>'; const d=rh.slice(-30); const W=300,H=80; const x=i=>i/(d.length-1)*(W-10)+5, y=r=>H-5-(r-3)/7*(H-10);
 return `<svg class="spark" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none"><line x1="0" x2="${W}" y1="${y(6)}" y2="${y(6)}" stroke="rgba(255,255,255,.15)" stroke-dasharray="4"/><line x1="0" x2="${W}" y1="${y(7.5)}" y2="${y(7.5)}" stroke="rgba(47,212,122,.25)" stroke-dasharray="4"/><polyline fill="none" stroke="#2fd47a" stroke-width="2.5" points="${d.map((r,i)=>x(i)+','+y(r[1])).join(' ')}"/>${d.map((r,i)=>`<circle cx="${x(i)}" cy="${y(r[1])}" r="3" fill="${r[3]?'#f5c542':'#fff'}"><title>${r[0]} ${r[2]}: ${r[1]}</title></circle>`).join('')}</svg>`; }
function player(id){ const p=S.P[id]; if(!p)return; const mine=p.t===S.me&&!p.scouted&&!p.ret; const a=avgR(p);
 const attrs=(p.pos==='GK'?['gk','phy','pas','spd']:['att','def','pas','tec','phy','spd']).map(k=>`<div class="attr"><span>${N.ATTRN[k]}</span><div class="bar"><i style="width:${p[k]}%"></i></div><b>${p[k]}</b></div>`).join('');
 const pot=p.pot-p.o; const potTxt=pot>=10?'⭐⭐⭐ огромный':pot>=5?'⭐⭐ высокий':pot>=2?'⭐ есть рост':'достиг пика';
 const pers=['чувствительный','уравновешенный','амбициозный'][p.pers];
 const last=(p.rh||[]).slice(-5).reverse().map(r=>`<span class="chip">${r[2]} ${rtB(r[1])}${r[3]?' ⚽'+r[3]:''}</span>`).join('');
 modal(`<div class="row" style="border:0">${posB(p)}<div class="f1"><h2 style="margin:0">${esc(p.n)}</h2><div class="sm mut">${p.age} лет · ${p.h?p.h+' см · ':''}${p.ft?({L:'левая',R:'правая',B:'обе ноги'})[p.ft]+(p.ft==='B'?'':' нога')+' · ':''}${p.lg&&T(p.lg)?T(p.lg).f+' ':''}${esc(p.club)}${p.div===2?' (2-й дивизион)':''} · ${T(p.t).f}${p.dual?' · 🛂 '+T(p.dual).f+' '+esc(T(p.dual).n):''}</div></div><span class="ovr" style="font-size:22px">${p.o}</span></div>
 <div class="grid2"><div class="card" style="margin:4px 0">${attrs}</div><div class="card" style="margin:4px 0;font-size:13px">
 <div>Потенциал: <b>${potTxt}</b></div><div>Характер: ${pers}</div><div>Форма: <b>${(+p.form).toFixed(1)}</b></div><div>Мораль: <b>${p.mor}</b></div><div class="bar"><i style="width:${p.mor}%"></i></div><div>Свежесть: <b>${Math.round(p.fit)}%</b></div><div class="bar"><i style="width:${p.fit}%"></i></div>
 ${p.inj?`<div class="red">🚑 Травма: ${p.inj} дн.</div>`:''}${p.sus?`<div class="red">🟥 Дисквалификация: ${p.sus} м.</div>`:''}<div class="sm mut">Жёлтых (накоплено): ${p.yc||0}</div></div></div>
 <div class="card" style="margin:4px 0"><div class="grid2 sm"><div>Матчи: <b>${p.caps}</b></div><div>Голы: <b>${p.g}</b></div><div>Передачи: <b>${p.a}</b></div><div>${p.pos==='GK'?'Сухие: <b>'+p.cs+'</b>':'Ср. оценка: <b>'+(a?a.toFixed(2):'—')+'</b>'}</div></div>
 <div class="sm mut" style="margin-top:6px">История оценок при вас (жёлтые точки — голы)</div>${spark(p.rh)}<div>${last}</div></div>
 ${mine?`<h3 class="sm mut">Разговор с игроком</h3><div class="tabs" style="flex-wrap:wrap">${[['praise','Похвалить'],['crit','Покритиковать'],['promise','Обещать место в старте'],['comp','Предупредить о конкуренции'],['rest','Дать отдохнуть']].map(([k,n])=>`<button class="btn sm" onclick="UI.talk(${id},'${k}')">${n}</button>`).join('')}</div><div id="talkr" class="sm" style="margin:6px 0"></div>`:''}
 <button class="btn gh w" onclick="UI.closeM();UI.refresh()">Закрыть</button>`); }
function talk(id,k){ const r=N.talk(S.P[id],k); const e=$('#talkr'); if(e)e.innerHTML=r; }
SCR.u21=()=>{ top('U-21 команда'); const ys=N.pool(S.me).filter(p=>p.age<=21).sort((a,b)=>b.pot-a.pot);
 V().innerHTML=`<div class="card"><h3>Молодёжная сборная</h3><p class="sm mut">Игроки до 21 года, не вызванные в первую команду, играют за U-21 в каждом окне и получают дополнительный прогресс. Академия (уровень ${S.u.infra.acad}) ежегодно выпускает новых игроков.</p></div>
 <div class="card">${ys.map(p=>`<div class="row">${posB(p)}<div class="f1 c" onclick="UI.player(${p.id})"><div class="b">${esc(p.n)}</div><div class="sm mut">${p.age} л · ${esc(p.club)} · потенциал <span class="gold">${p.pot}</span></div></div><span class="ovr">${p.o}</span><button class="btn sm ${S.u.call.includes(p.id)?'':'g'}" onclick="UI.toggleCall(${p.id},${!S.u.call.includes(p.id)})">${S.u.call.includes(p.id)?'В основе':'Вызвать'}</button></div>`).join('')||'<div class="mut">Нет игроков до 21 года</div>'}</div>
 <div class="card"><h3>Результаты U-21</h3>${S.u.u21.res.map(r=>`<div class="row"><span class="sm mut">${N.fmtD(r.d,1)}</span><div class="f1">U-21 ${tf(S.me)} — ${tf(r.o)} ${esc(T(r.o).n)}</div><b class="${r.s[0]>r.s[1]?'grn':r.s[0]<r.s[1]?'red':'gold'}">${r.s.join(':')}</b></div>${r.sc.length?`<div class="sm mut" style="margin:-4px 0 4px">⚽ ${r.sc.join(', ')}</div>`:''}`).join('')||'<div class="mut sm">Матчей ещё не было</div>'}</div>`; };
const MENT=['Глухая оборона','Оборона','Баланс','Атака','Все в атаку'], PRESS=['Низкий','Средний','Высокий'], TEMPO=['Медленный','Обычный','Быстрый'], STYLE={mix:'Смешанный',short:'Короткий пас',long:'Длинные передачи',counter:'Контратаки'};
const INSTR={'':'Стандартно',att:'Больше атаковать',hold:'Держать позицию',free:'Свободная роль',mark:'Персональная опека'};
function tacPanel(tac,fn){ const sel=(lab,key,opts,val)=>`<div style="margin:6px 0"><div class="sm mut">${lab}</div><select onchange="${fn}('${key}',this.value)">${opts.map(([v,n])=>`<option value="${v}" ${String(v)===String(val)?'selected':''}>${n}</option>`).join('')}</select></div>`;
 return sel('Настрой','ment',MENT.map((n,i)=>[i-2,n]),tac.ment)+sel('Прессинг','press',PRESS.map((n,i)=>[i,n]),tac.press)+sel('Темп','tempo',TEMPO.map((n,i)=>[i,n]),tac.tempo)+sel('Стиль','style',Object.entries(STYLE),tac.style); }
function pitchHTML(form,ids){ const F=N.FORMS[form]; return `<div class="pitch" id="pitch"><div class="ln" style="left:-2px;right:-2px;top:50%;height:0"></div><div class="ln" style="left:35%;width:30%;top:44%;height:12%;border-radius:50%"></div><div class="ln" style="left:22%;width:56%;bottom:-2px;height:15%"></div><div class="ln" style="left:22%;width:56%;top:-2px;height:15%"></div>
 ${F.map(([role,x,y],i)=>{ const p=ids[i]&&S.P[ids[i]]; const v=p?Math.round(N.roleOvr(p,role)):0; const bad=p&&(N.compat(p.pos,role)<0.9||p.inj||p.sus);
  return `<div class="tok ${role==='GK'?'gk':''} ${bad?'bad':''} ${st.sel&&st.sel.k==='s'&&st.sel.i===i?'sel':''}" data-slot="${i}" style="left:${x}%;top:${96-y*0.9}%"><div class="dot">${p?v:'+'}</div><div class="nmt">${p?esc(short(p)):'—'}</div><div class="rl">${N.POS[role][0]}${p&&S.u.instr[p.id]?' ★':''}</div></div>`; }).join('')}</div>`; }
SCR.tactics=()=>{ top('Тактика'); if(!S.u.xi||(!N.validXI()&&S.u.xi.s.every(id=>!id))) N.autoXI(); const x=S.u.xi; x.b=S.u.call.filter(id=>!x.s.includes(id)); const bench=x.b.map(id=>S.P[id]).filter(Boolean);
 const xiOvr=Math.round(x.s.reduce((s,id,i)=>s+(id?N.roleOvr(S.P[id],N.FORMS[x.form][i][0]):0),0)/11);
 V().innerHTML=`<div class="card"><div class="row" style="border:0"><select style="flex:1" onchange="UI.setForm(this.value)">${Object.keys(N.FORMS).map(f=>`<option ${f===x.form?'selected':''}>${f}</option>`).join('')}</select><span class="ovr">${xiOvr}</span><button class="btn sm" onclick="UI.autoXIbtn()">Автосостав</button></div>
 <div class="sm mut" style="margin:4px 0">Перетащите игрока на другого или нажмите двух игроков по очереди, чтобы поменять их местами. Повторное нажатие — индивидуальная установка. Красная обводка — не своя позиция / недоступен.</div>
 ${pitchHTML(x.form,x.s)}</div>
 <div class="card"><h3>Запасные (${bench.length})</h3><div class="bench">${bench.map(p=>`<div class="bp ${st.sel&&st.sel.k==='b'&&st.sel.id===p.id?'sel':''}" data-pid="${p.id}">${posB(p)} ${esc(short(p))} <b>${p.o}</b>${p.inj?' 🚑':''}${p.sus?' 🟥':''}</div>`).join('')||'<span class="mut sm">Вызовите больше игроков</span>'}</div></div>
 <div class="card"><h3>Командные установки</h3>${tacPanel(S.u.tac,'UI.setTac')}</div>`; bindPitch(); };
function setForm(f){ const x=S.u.xi; const ps=x.s.map(id=>S.P[id]).filter(Boolean);
 const F=N.FORMS[f]; const used=new Set(); const ns=new Array(11).fill(null); const order=F.map((_,i)=>i).sort((a,b)=>(F[a][0]==='GK'?-1:0)-(F[b][0]==='GK'?-1:0));
 for(const i of order){ const role=F[i][0]; let best=null,bv=-1; for(const p of ps){ if(used.has(p.id))continue; const v=N.roleOvr(p,role); if(v>bv){bv=v;best=p;} } if(best){used.add(best.id);ns[i]=best.id;} }
 x.form=f; x.s=ns; refresh(); }
function autoXIbtn(){ N.autoXI(S.u.xi&&S.u.xi.form); refresh(); toast('Лучший состав выставлен'); }
function setTac(k,v){ S.u.tac[k]=k==='style'?v:+v; }
function swapSel(a,b){ const x=S.u.xi; const A=a.k==='s'?x.s[a.i]:a.id, B=b.k==='s'?x.s[b.i]:b.id;
 if(a.k==='s'&&b.k==='s'){ x.s[a.i]=B; x.s[b.i]=A; } else if(a.k==='s'){ x.s[a.i]=B; } else if(b.k==='s'){ x.s[b.i]=A; }
 x.b=S.u.call.filter(id=>!x.s.includes(id)); }
function tapSel(s){ if(st.sel){ const a=st.sel; st.sel=null; if(a.k==='s'&&s.k==='s'&&a.i===s.i){ const id=S.u.xi.s[s.i]; if(id) instrModal(id); return refresh(); } if(a.k==='b'&&s.k==='b'){ st.sel=s; return refresh(); } swapSel(a,s); return refresh(); } st.sel=s; refresh(); }
function instrModal(id){ const p=S.P[id]; modal(`<h2>${esc(p.n)}</h2><div class="sm mut">Индивидуальная установка</div>${Object.entries(INSTR).map(([k,n])=>`<div class="row c" onclick="UI.setInstr(${id},'${k}')"><span>${(S.u.instr[id]||'')===k?'🔘':'⚪'}</span><div class="f1">${n}</div></div>`).join('')}<div style="height:6px"></div><button class="btn gh w" onclick="UI.player(${id})">Карточка игрока</button>`); }
function setInstr(id,k){ if(k)S.u.instr[id]=k; else delete S.u.instr[id]; closeM(); refresh(); }
function bindPitch(){ const root=V(); let drag=null;
 root.querySelectorAll('.tok,.bp').forEach(el=>{ el.addEventListener('pointerdown',e=>{ e.preventDefault(); const s=el.dataset.slot!==undefined?{k:'s',i:+el.dataset.slot}:{k:'b',id:+el.dataset.pid}; drag={el,s,x:e.clientX,y:e.clientY,moved:false}; try{el.setPointerCapture(e.pointerId)}catch(_){} });
  el.addEventListener('pointermove',e=>{ if(!drag||drag.el!==el)return; const dx=e.clientX-drag.x,dy=e.clientY-drag.y; if(!drag.moved&&Math.hypot(dx,dy)>8){drag.moved=true;el.classList.add('drag');} if(drag.moved){ el.style.transform=el.classList.contains('bp')?`translate(${dx}px,${dy}px)`:`translate(calc(-50% + ${dx}px),calc(-50% + ${dy}px))`; } });
  el.addEventListener('pointerup',e=>{ if(!drag||drag.el!==el)return; const d=drag; drag=null; if(!d.moved){ tapSel(d.s); return; } el.style.visibility='hidden'; const t=document.elementFromPoint(e.clientX,e.clientY); el.style.visibility=''; const tgt=t&&t.closest('.tok,.bp'); st.sel=null;
   if(tgt&&tgt!==el){ const s2=tgt.dataset.slot!==undefined?{k:'s',i:+tgt.dataset.slot}:{k:'b',id:+tgt.dataset.pid}; swapSel(d.s,s2); } refresh(); }); }); }
SCR.training=()=>{ top('Тренировка'); const t=S.u.train; const F={bal:['⚖️','Сбалансированно','Понемногу всё'],att:['🎯','Атака','Атака и техника'],def:['🛡️','Оборона','Оборона и физика'],phys:['💪','Физподготовка','Физика и скорость'],tec:['🎩','Техника и пас','Пас и техника'],tac:['🧠','Тактика','Сыгранность: рост формы'],gk:['🧤','Вратари','Отдельная работа с вратарями'],rest:['🛌','Восстановление','Свежесть и мораль, без прогресса']};
 V().innerHTML=`<div class="card"><h3>Фокус сборов</h3><p class="sm mut">Тренировка проводится в начале каждого международного окна для вызванных игроков. Тренировочная база: уровень ${S.u.infra.base}.</p>${Object.entries(F).map(([k,[i,n,d]])=>`<div class="row c" onclick="UI.S().u.train.f='${k}';UI.refresh()"><span style="font-size:22px">${i}</span><div class="f1"><div class="b">${n}</div><div class="sm mut">${d}</div></div><span>${t.f===k?'✅':''}</span></div>`).join('')}</div>
 <div class="card"><h3>Интенсивность</h3><div class="tabs">${['Лёгкая','Нормальная','Высокая (риск травм)'].map((n,i)=>`<div class="tab ${t.i===i?'on':''}" onclick="UI.S().u.train.i=${i};UI.refresh()">${n}</div>`).join('')}</div></div>
 <div class="card"><h3>Состояние вызванных</h3>${S.u.call.map(id=>S.P[id]).filter(Boolean).map(p=>`<div class="row">${posB(p)}<div class="f1">${esc(short(p))}</div><div style="width:90px"><div class="bar"><i style="width:${p.fit}%"></i></div></div><span class="sm">${Math.round(p.fit)}%</span><span class="sm">Ф ${(+p.form).toFixed(1)}</span></div>`).join('')}</div>`; };
SCR.fed=()=>{ top('Федерация'); const ex=Object.values(S.C).filter(c=>c.stage!=='done'&&c.stage!=='pending'&&(c.teams||[]).includes(S.me));
 V().innerHTML=`<div class="card"><h3>Доверие федерации</h3><div class="b" style="font-size:28px">${S.u.trust}%</div><div class="bar t"><i style="width:${S.u.trust}%"></i></div><p class="sm mut">${S.u.trust>=75?'Федерация в восторге от вашей работы.':S.u.trust>=50?'Федерация довольна.':S.u.trust>=25?'Федерация обеспокоена результатами.':'Ваше положение под угрозой!'} При падении до 12% вас уволят.</p></div>
 <div class="card"><h3>Задачи</h3>${ex.map(c=>`<div class="row"><div class="f1">${esc(c.n)}</div><span class="sm">${esc((N.expectText(c)||'').replace('Задача федерации: ','').replace('Задача: ',''))}</span></div>`).join('')||'<div class="mut sm">Нет активных турниров</div>'}</div>
 <div class="card"><h3>Инфраструктура · бюджет <span class="gold">${S.u.bud}</span></h3><p class="sm mut">Бюджет пополняется за победы, выход в финальные турниры и трофеи.</p>${Object.entries(N.INFRA).map(([k,[n,d]])=>{ const l=S.u.infra[k]; const c=N.infraCost(l); return `<div class="row"><div class="f1"><div class="b">${n} <span class="gold">${'■'.repeat(l)}${'□'.repeat(5-l)}</span></div><div class="sm mut">${d}</div></div>${l<5?`<button class="btn sm ${S.u.bud>=c?'g':''}" ${S.u.bud>=c?'':'disabled'} onclick="UI.upg('${k}')">${c} 💰</button>`:'<span class="grn sm">MAX</span>'}</div>`; }).join('')}</div>
 <div class="card"><h3>Карьера</h3>${S.u.teams.map(x=>`<div class="row">${tf(x.c)}<div class="f1">${esc(T(x.c).n)}</div><span class="sm mut">с ${N.fmtD(x.from,1)}</span></div>`).join('')}</div>`; };
function upg(k){ if(N.upgrade(k)){toast('Объект улучшен!');save();} refresh(); }
function nlCard(){ const conf=T(S.me).conf; if(!N.NLS[conf]) return ''; const st=N.nlState(conf); const L=N.nlLeagueOf(conf,S.me); const nx=st.next&&Object.keys(st.next).find(k=>st.next[k].includes(S.me));
 return `<div class="card"><h3>${N.NLS[conf].n}</h3><div class="sm">Мы в <b>Лиге ${L}</b>${nx&&nx!==L?` · в следующем розыгрыше: <b class="${nx<L?'grn':'red'}">Лига ${nx}</b>`:''}. Победители групп поднимаются, последние места — вылетают${conf==='UEFA'?'; 3-и места A/B и 2-е места B/C играют двухматчевые стыки за место в лиге':''}.</div></div>`; }
function compsList(){ const my=T(S.me).conf; return Object.values(S.C).filter(c=>c.kind!=='fr'&&c.stage!=='pending').sort((a,b)=>((b.teams||[]).includes(S.me)-(a.teams||[]).includes(S.me))||((b.conf===my||b.conf==='ALL')-(a.conf===my||a.conf==='ALL'))||((a.stage==='done')-(b.stage==='done'))); }
SCR.comps=()=>{ top('Соревнования'); const cs=compsList(); const pend=Object.values(S.C).filter(c=>c.stage==='pending'&&(c.conf===T(S.me).conf||c.conf==='ALL'));
 V().innerHTML=`<div class="card"><h3>Товарищеские матчи</h3><button class="btn w" onclick="UI.friendly()">➕ Назначить товарищеский матч</button></div>
 ${nlCard()}<div class="card"><h3>Турниры</h3>${cs.map(c=>`<div class="row c" onclick="UI.go('comp','${c.id}')"><span>${(c.teams||[]).includes(S.me)?'⭐':'🏆'}</span><div class="f1"><div class="b">${esc(c.n)}</div><div class="sm mut">${c.stage==='done'?'Завершён'+(c.w?' · победитель '+tn(c.w):''):c.stage==='ko'?'Плей-офф':'Групповой этап'}</div></div>›</div>`).join('')||'<div class="mut sm">Турниры ещё не стартовали</div>'}</div>
 <div class="card"><h3>Впереди</h3>${pend.map(c=>`<div class="row"><div class="f1">${esc(c.n)}</div><span class="sm mut">${c.gd?N.fmtD(c.gd[0],1):''}</span></div>`).join('')||'<div class="mut sm">—</div>'}</div>
 <div class="card"><h3>Архив победителей</h3>${S.arch.filter(a=>a.kind!=='qual'&&a.w).slice(-40).reverse().map(a=>`<div class="row"><div class="f1 sm">${esc(a.n)}</div><span class="sm">${tn(a.w)}</span></div>`).join('')||'<div class="mut sm">Пока пусто</div>'}</div>`; };
SCR.comp=(id)=>{ const c=S.C[id]; if(!c)return back(); top(c.n); const hasG=c.groups&&c.groups.length; const tab=(st.tab.c==='tab'&&!hasG?null:st.tab.c)||(hasG?'tab':'ko'); const tabs=[...(hasG?[['tab','Таблицы']]:[]),...(c.ko?[['ko','Плей-офф']]:[]),['fx','Матчи'],['sc','Бомбардиры']];
 let body='';
 if(tab==='tab'){ const rk=c.kind==='qual'?N.ranking(c).slice(0,c.slots).map(r=>r.t):[]; const adv=c.adv?c.adv.per:0;
  const grps=c.groups.slice().sort((a,b)=>(b.t.includes(S.me))-(a.t.includes(S.me)));
  body=grps.map(g=>`<div class="card"><h3>${g.n?'Группа '+g.n:'Таблица'}</h3><table><tr><th>#</th><th class="l">Команда</th><th>И</th><th>В</th><th>Н</th><th>П</th><th>Р</th><th>О</th></tr>${N.table(c,g.n).map((r,i)=>`<tr class="${r.t===S.me?'me':''} ${(c.kind==='qual'&&rk.includes(r.t))||(i<adv)?'q':''}"><td>${i+1}</td><td class="l">${T(r.t).f} ${esc(T(r.t).n)}</td><td>${r.p}</td><td>${r.w}</td><td>${r.d}</td><td>${r.l}</td><td>${r.gf}-${r.ga}</td><td class="b">${r.pts}</td></tr>`).join('')}</table></div>`).join('');
  if(c.kind==='qual') body=`<div class="card sm mut">Путёвок: ${c.slots}. Зелёная метка — сейчас в зоне выхода (лучшие среди занявших одинаковые места сравниваются по очкам за матч).</div>`+body;
  if(c.adv&&c.adv.best) body=`<div class="card sm mut">В плей-офф выходят по ${c.adv.per} лучших из групп и ${c.adv.best} лучших команд, занявших 3-и места.</div>`+body; }
 if(tab==='ko'&&c.ko){ body=`<div class="card"><div class="bracket">${c.ko.map(rd=>`<div class="col"><div class="sm mut b">${esc(S.F.find(f=>f.id===rd[0].f).st)}</div>${rd.map(t=>{ const f=S.F.find(x=>x.id===t.f); const r=f.r; if(t.f1) return tie2(t,f); return `<div class="tie" ${f.u&&r?`onclick="UI.matchDet(${f.id})" style="cursor:pointer"`:''}><div class="${r&&r.w===f.h?'w':''}">${T(f.h).f} ${esc(T(f.h).n)} <b style="float:right">${r?r.hg:''}</b></div><div class="${r&&r.w===f.a?'w':''}">${T(f.a).f} ${esc(T(f.a).n)} <b style="float:right">${r?r.ag:''}</b></div>${r&&r.pen?`<div class="sm mut">пен. ${r.pen.join(':')}</div>`:r&&r.et?'<div class="sm mut">д.в.</div>':''}${r?'':`<div class="sm mut">${N.fmtD(f.d,1)}</div>`}</div>`; }).join('')}</div>`).join('')}${c.w?`<div class="col ctr"><div class="sm mut b">Чемпион</div><div style="font-size:48px">🏆</div><div class="b">${tn(c.w)}</div></div>`:''}</div></div>`; }
 if(tab==='fx'){ const fx=S.F.filter(f=>f.c===id).sort((a,b)=>a.d<b.d?-1:1); const mine=st.tab.cm; const list=mine?fx.filter(f=>f.h===S.me||f.a===S.me):fx;
  body=`<div class="card"><label class="ck"><input type="checkbox" ${mine?'checked':''} onchange="UI.st.tab.cm=this.checked;UI.refresh()"> Только наши матчи</label></div><div class="card">${list.slice(-150).map(f=>fixRow(f,false)+`<div class="sm mut ctr" style="margin-top:-4px">${esc(f.st)} · ${N.fmtD(f.d,1)}</div>`).join('')}</div>`; }
 if(tab==='sc'){ const ts=N.topScorers(id).slice(0,25); body=`<div class="card"><table><tr><th>#</th><th class="l">Игрок</th><th class="l">Сборная</th><th>Г</th><th>П</th></tr>${ts.map((x,i)=>`<tr class="${x.t===S.me?'me':''}"><td>${i+1}</td><td class="l">${esc(x.n)}</td><td class="l">${T(x.t).f}</td><td class="b">${x.g}</td><td>${x.a}</td></tr>`).join('')}</table>${ts.length?'':'<div class="mut sm">Голов ещё не было</div>'}</div>`; }
 V().innerHTML=`<div class="tabs">${tabs.map(([k,n])=>`<div class="tab ${tab===k?'on':''}" onclick="UI.st.tab.c='${k}';UI.refresh()">${n}</div>`).join('')}</div>`+body; };
function tie2(t,f2){ const f1=S.F.find(x=>x.id===t.f1); const r1=f1&&f1.r, r2=f2.r; const g=(side)=> side==='h'? [r1?r1.hg:'',r2?r2.ag:''] : [r1?r1.ag:'',r2?r2.hg:''];
 const H=g('h'),A=g('a'); const tot=x=>x[0]===''?'':(+x[0])+(x[1]===''?0:+x[1]); const cl=(fx)=>fx&&fx.u&&fx.r?`onclick="UI.matchDet(${fx.id})" style="cursor:pointer"`:'';
 return `<div class="tie"><div class="${t.w===t.h?'w':''}">${T(t.h).f} ${esc(T(t.h).n)} <b style="float:right">${tot(H)}</b></div><div class="${t.w===t.a?'w':''}">${T(t.a).f} ${esc(T(t.a).n)} <b style="float:right">${tot(A)}</b></div>
 <div class="sm mut"><span ${cl(f1)}>1-й: ${r1?r1.hg+':'+r1.ag:N.fmtD(f1.d,1)}</span> · <span ${cl(f2)}>2-й: ${r2?r2.hg+':'+r2.ag+(r2.pen?' (пен. '+r2.pen.join(':')+')':r2.et?' д.в.':''):N.fmtD(f2.d,1)}</span></div></div>`; }
function friendly(){ const ds=N.freeDates(); if(!ds.length) return toast('Нет свободных дат в ближайших окнах');
 const me=T(S.me); const opps=Object.values(S.T).filter(t=>t.c!==S.me).sort((a,b)=>Math.abs(a.elo-me.elo)-Math.abs(b.elo-me.elo)).slice(0,70).sort((a,b)=>b.elo-a.elo);
 modal(`<h2>Товарищеский матч</h2><div class="sm mut">Дата (свободные даты международных окон)</div><select id="frd">${ds.map(d=>`<option value="${d}">${N.fmtD(d)}</option>`).join('')}</select><div style="height:8px"></div><div class="sm mut">Соперник</div><select id="fro">${opps.map(t=>`<option value="${t.c}">${t.n} — ${N.stars(t)}★</option>`).join('')}</select>
 <div style="height:8px"></div><label class="ck"><input type="checkbox" id="frh" checked> Играем дома</label><div style="height:10px"></div><button class="btn g w" onclick="UI.doFriendly()">Назначить</button><div style="height:6px"></div><button class="btn gh w" onclick="UI.closeM()">Отмена</button>`); }
function doFriendly(){ const d=$('#frd').value,o=$('#fro').value,h=$('#frh').checked; if(N.schedFriendly(d,o,h)){ toast('Матч назначен: '+N.fmtD(d,1)+' — '+T(o).n); save(); closeM(); refresh(); } else toast('Соперник занят в эту дату'); }
SCR.stats=()=>{ top('Статистика'); const tab=st.tab.s||'pl'; const tabs=[['pl','Игроки'],['mt','Матчи'],['sc','Бомбардиры'],['rec','Рекорды'],['rk','Рейтинг'],['tr','Трофеи']];
 let body=''; const all=Object.values(S.P).filter(p=>p.t===S.me&&!p.scouted);
 if(tab==='pl'){ const srt=st.tab.ps||'caps'; const val={caps:p=>p.caps,g:p=>p.g,a:p=>p.a,cs:p=>p.cs,avg:p=>avgR(p)||0,o:p=>p.o,age:p=>-p.age,n:p=>(p.rh||[]).length}; const ps=all.filter(p=>!p.ret||st.tab.pr).sort((a,b)=>val[srt](b)-val[srt](a));
  const th=(k,n)=>`<th onclick="UI.st.tab.ps='${k}';UI.refresh()" class="${srt===k?'grn':''}">${n}</th>`;
  body=`<div class="card"><label class="ck"><input type="checkbox" ${st.tab.pr?'checked':''} onchange="UI.st.tab.pr=this.checked;UI.refresh()"> Включая завершивших карьеру</label><div class="sm mut">И — матчи за сборную всего, М — матчи при вас, Оц — средняя оценка при вас. Нажмите на заголовок для сортировки.</div></div><div class="card" style="overflow-x:auto"><table><tr><th></th><th class="l">Игрок</th>${th('age','Воз')}${th('o','Сила')}${th('caps','И')}${th('n','М')}${th('g','Г')}${th('a','П')}${th('cs','Сух')}${th('avg','Оц')}</tr>${ps.map(p=>{const a=avgR(p);return `<tr onclick="UI.player(${p.id})" style="cursor:pointer"><td>${posB(p)}</td><td class="l">${esc(short(p))}${p.ret?' <span class="mut">(зав.)</span>':''}</td><td>${p.age}</td><td>${p.o}</td><td>${p.caps}</td><td>${(p.rh||[]).length}</td><td>${p.g}</td><td>${p.a}</td><td>${p.pos==='GK'?p.cs:'–'}</td><td>${a?rtB(a):'–'}</td></tr>`}).join('')}</table></div>`; }
 if(tab==='mt'){ const ms=S.F.filter(f=>f.u&&f.r).sort((a,b)=>a.d<b.d?1:-1); body=`<div class="card"><div class="sm mut">Всего матчей: ${ms.length}. Нажмите на матч для подробностей (события, статистика, оценки).</div></div><div class="card">${ms.map(f=>fixRow(f)).join('')||'<div class="mut">Матчей ещё не было</div>'}</div>`; }
 if(tab==='sc'){ const cs=Object.values(S.C).filter(c=>c.kind!=='fr'&&c.stage!=='pending'); const cid=st.tab.scc&&S.C[st.tab.scc]?st.tab.scc:(cs.find(c=>(c.teams||[]).includes(S.me))||cs[0]||{}).id;
  const ts=cid?N.topScorers(cid).slice(0,30):[]; body=`<div class="card"><select onchange="UI.st.tab.scc=this.value;UI.refresh()">${cs.map(c=>`<option value="${c.id}" ${c.id===cid?'selected':''}>${esc(c.n)}</option>`).join('')}</select></div><div class="card"><table><tr><th>#</th><th class="l">Игрок</th><th></th><th>Г</th><th>П</th></tr>${ts.map((x,i)=>`<tr class="${x.t===S.me?'me':''}"><td>${i+1}</td><td class="l">${esc(x.n)}</td><td>${T(x.t).f}</td><td class="b">${x.g}</td><td>${x.a}</td></tr>`).join('')}</table></div>
  <div class="card"><h3>Архив бомбардиров</h3>${S.arch.filter(a=>a.ts&&a.ts[0]&&a.kind==='final').map(a=>`<div class="row sm"><div class="f1">${esc(a.n)}</div>${esc(a.ts[0].n)} ${T(a.ts[0].t).f} — ${a.ts[0].g}</div>`).join('')||'<div class="mut sm">Появится после завершения четырёхлетнего цикла</div>'}</div>`; }
 if(tab==='rec'){ const ms=S.F.filter(f=>f.u&&f.r&&(f.h===S.me||f.a===S.me)).sort((a,b)=>a.d<b.d?-1:1); const gd=f=>(f.h===S.me?1:-1)*(f.r.hg-f.r.ag); const res=f=>f.r.w?(f.r.w===S.me?1:-1):Math.sign(gd(f));
  let bw=null,bl=null,ws=0,us=0,cw=0,cu=0,csn=0; for(const f of ms){ if(!bw||gd(f)>gd(bw))bw=f; if(!bl||gd(f)<gd(bl))bl=f; const r=res(f); cw=r>0?cw+1:0; cu=r>=0?cu+1:0; ws=Math.max(ws,cw); us=Math.max(us,cu); if((f.h===S.me?f.r.ag:f.r.hg)===0)csn++; }
  const best=(fn,flt=()=>true)=>all.filter(flt).sort((a,b)=>fn(b)-fn(a))[0]; const sc=best(p=>p.g), cp=best(p=>p.caps), as=best(p=>p.a), gk=best(p=>p.cs,p=>p.pos==='GK'), ar=best(p=>avgR(p)||0,p=>p.rh&&p.rh.length>=5);
  let topM=null; for(const f of ms) if(f.r.det) for(const p of f.r.det.ps) if(p[2]===(f.h===S.me?0:1)&&(!topM||p[3]>topM[0][3])) topM=[p,f];
  const rr=(n,v)=>`<div class="row"><div class="f1 mut">${n}</div><div class="right b">${v}</div></div>`;
  body=`<div class="card"><h3>Рекорды сборной (при вас)</h3>${rr('Самая крупная победа',bw&&gd(bw)>0?`${tn(bw.h)} ${bw.r.hg}:${bw.r.ag} ${tn(bw.a)}`:'—')}${rr('Самое крупное поражение',bl&&gd(bl)<0?`${tn(bl.h)} ${bl.r.hg}:${bl.r.ag} ${tn(bl.a)}`:'—')}${rr('Победная серия',ws)}${rr('Беспроигрышная серия',us)}${rr('Матчи «на ноль»',csn)}${rr('Тренерский баланс',`${S.u.stat.w}-${S.u.stat.d}-${S.u.stat.l}, мячи ${S.u.stat.gf}:${S.u.stat.ga}`)}${rr('Процент побед',ms.length?Math.round(S.u.stat.w/Math.max(1,S.u.stat.w+S.u.stat.d+S.u.stat.l)*100)+'%':'—')}</div>
  <div class="card"><h3>Рекорды игроков</h3>${rr('Лучший бомбардир',sc?esc(sc.n)+' — '+sc.g:'—')}${rr('Больше всего матчей',cp?esc(cp.n)+' — '+cp.caps:'—')}${rr('Больше всего передач',as?esc(as.n)+' — '+as.a:'—')}${rr('Сухие матчи (вратарь)',gk?esc(gk.n)+' — '+gk.cs:'—')}${rr('Лучшая ср. оценка (5+ матчей)',ar?esc(ar.n)+' — '+avgR(ar).toFixed(2):'—')}${rr('Лучшая оценка за матч',topM?esc(topM[0][1])+' — '+topM[0][3]+' ('+esc(T(topM[1].h===S.me?topM[1].a:topM[1].h).n)+')':'—')}</div>`; }
 if(tab==='rk'){ const ts=Object.values(S.T).sort((a,b)=>b.elo-a.elo); const cf=st.tab.rkc||'ALL'; body=`<div class="tabs">${['ALL',...Object.keys(N.CONFS)].map(k=>`<div class="tab ${cf===k?'on':''}" onclick="UI.st.tab.rkc='${k}';UI.refresh()">${k==='ALL'?'Мир':k}</div>`).join('')}</div><div class="card"><table><tr><th>#</th><th class="l">Сборная</th><th>Сила</th><th>Эло</th></tr>${ts.map((t,i)=>[t,i]).filter(([t])=>cf==='ALL'||t.conf===cf).map(([t,i])=>`<tr class="${t.c===S.me?'me':''}"><td>${i+1}</td><td class="l">${t.f} ${esc(t.n)}</td><td>${stars(t)}</td><td class="b">${t.elo}</td></tr>`).join('')}</table></div>`; }
 if(tab==='tr'){ body=`<div class="card"><h3>Трофеи</h3>${S.u.tro.map(t=>`<div class="trophy"><span class="i">🏆</span><b>${esc(t.n)}</b><span class="mut">${T(t.t).f} ${N.fmtD(t.d,1)}</span></div>`).join('')||'<div class="mut">Трофеев пока нет. Всё впереди!</div>'}</div>
  <div class="card"><h3>Достижения (${Object.keys(S.u.ach).length}/${Object.keys(N.ACH).length})</h3>${Object.entries(N.ACH).map(([k,[n,d]])=>`<div class="row ach ${S.u.ach[k]?'on':''}"><span style="font-size:22px">${S.u.ach[k]?'🏅':'🔒'}</span><div class="f1"><div class="b">${n}</div><div class="sm mut">${d}${S.u.ach[k]?' · '+N.fmtD(S.u.ach[k],1):''}</div></div></div>`).join('')}</div>`; }
 V().innerHTML=`<div class="tabs">${tabs.map(([k,n])=>`<div class="tab ${tab===k?'on':''}" onclick="UI.st.tab.s='${k}';UI.refresh()">${n}</div>`).join('')}</div>`+body; };
function matchDet(fid){ const f=S.F.find(x=>x.id===fid); if(!f||!f.r)return; const r=f.r, d=r.det; let h=`<div class="sb"><div class="tm">${tf(f.h)}${esc(T(f.h).n)}</div><div class="ctr"><div class="sc">${r.hg}:${r.ag}</div><div class="mn">${r.pen?'пен. '+r.pen.join(':'):r.et?'д.в.':''}</div></div><div class="tm">${tf(f.a)}${esc(T(f.a).n)}</div></div><div class="ctr sm mut" style="margin:6px">${esc(cName(f))} · ${esc(f.st)} · ${N.fmtD(f.d)}${r.agg?' · по сумме '+r.agg[0]+':'+r.agg[1]:''}${r.att?' · '+(N.WXN[r.wx]||'')+' · зрителей '+r.att.toLocaleString('ru-RU'):''}</div>`;
 if(d){ h+=`<div class="card">${d.ev.map(e=>`<div class="sm"><b class="gold">${e[0]}'</b> ${esc(e[3])}</div>`).join('')||'<div class="sm mut">Без событий</div>'}</div>`+statsHTML(d.st)+ratingsHTML(d.ps,f); }
 modal(h+`<button class="btn gh w" onclick="UI.closeM()">Закрыть</button>`); }
function statsHTML(stt){ const tot=Math.max(1,stt[0].poss+stt[1].poss); const rows=[['Владение',Math.round(stt[0].poss/tot*100)+'%',Math.round(stt[1].poss/tot*100)+'%',stt[0].poss,stt[1].poss],['Удары',stt[0].sh,stt[1].sh],['В створ',stt[0].sot,stt[1].sot],['xG (ожидаемые голы)',stt[0].xg.toFixed(2),stt[1].xg.toFixed(2),stt[0].xg,stt[1].xg],['Угловые',stt[0].co,stt[1].co],['Фолы',stt[0].fo,stt[1].fo],['Жёлтые',stt[0].yc,stt[1].yc],['Красные',stt[0].rc,stt[1].rc],['Офсайды',stt[0].off,stt[1].off]];
 return `<div class="card">${rows.map(([n,a,b,x,y])=>{ x=x??a; y=y??b; const t=(+x)+(+y)||1; return `<div class="sm ctr mut">${n}</div><div class="sbar"><span class="v">${a}</span><div class="tr"><i style="width:${(+x)/t*100}%"></i></div><span class="v">${b}</span></div>`; }).join('')}</div>`; }
function ratingsHTML(ps,f){ const side=s=>ps.filter(p=>p[2]===s&&p[6]>0).sort((a,b)=>'GDMF'.indexOf(N.POS[a[7]][1])-'GDMF'.indexOf(N.POS[b[7]][1]));
 const col=s=>side(s).map(p=>`<div class="row sm"><span class="pos p${N.POS[p[7]][1]}">${N.POS[p[7]][0]}</span><div class="f1" ${S.P[p[0]]?`onclick="UI.player(${p[0]})" style="cursor:pointer"`:''}>${esc(p[1].split(' ').slice(-1)[0])} ${'⚽'.repeat(p[4])}${p[5]?'🅰️'.repeat(p[5]):''}${p[8]?'🟨':''}${p[9]?'🟥':''}${p[10]?'🚑':''}</div><span class="mut">${p[6]}'</span>${rtB(p[3])}</div>`).join('');
 const mvp=ps.filter(p=>p[6]>0).sort((a,b)=>b[3]-a[3])[0];
 return `<div class="card"><h3>Оценки игроков ${mvp?'· лучший: '+esc(mvp[1])+' '+rtB(mvp[3]):''}</h3><div class="grid2"><div><div class="ctr b">${tf(f.h)}</div>${col(0)}</div><div><div class="ctr b">${tf(f.a)}</div>${col(1)}</div></div></div>`; }
SCR.settings=()=>{ top('Настройки'); const m=meta();
 V().innerHTML=`<div class="card"><h3>Сохранения</h3><div class="sm mut">Игра автоматически сохраняется в текущий слот после каждого шага и матча.</div>${[1,2,3].map(i=>`<div class="row"><div class="f1"><div class="b">Слот ${i} ${S&&S.slot===i?'<span class="grn sm">(текущий)</span>':''}</div><div class="sm mut">${m[i]?(N.TEAMS.find(t=>t.c===m[i].t)||{f:''}).f+' '+esc(m[i].c)+' · '+N.fmtD(m[i].d,1):'пусто'}</div></div><button class="btn sm g" onclick="UI.saveTo(${i})">Сохранить</button>${m[i]?`<button class="btn sm" onclick="UI.loadFrom(${i})">Загрузить</button><button class="btn sm r" onclick="UI.delSlot(${i})">✕</button>`:''}</div>`).join('')}
 <div style="height:8px"></div><div class="grid2"><button class="btn" onclick="UI.exportSave()">⬇ Экспорт в файл</button><label class="btn">⬆ Импорт<input type="file" accept=".nfm,.txt" style="display:none" onchange="UI.importSave(this)"></label></div></div>
 <div class="card"><h3>Матч</h3><div class="sm mut">Скорость по умолчанию</div><div class="tabs">${['×1','×2','×4','×8'].map((n,i)=>`<div class="tab ${PREF.spd===i?'on':''}" onclick="UI.PREF.spd=${i};UI.savePref();UI.refresh()">${n}</div>`).join('')}</div>
 <label class="ck" style="margin-top:8px"><input type="checkbox" ${PREF.brief?'checked':''} onchange="UI.PREF.brief=this.checked;UI.savePref()"> Только ключевые события в комментариях</label></div>
 <div class="card"><h3>Тренер</h3><input type="text" value="${esc(S.coach)}" onchange="UI.S().coach=this.value;UI.save()"></div>
 <div class="card"><button class="btn w" onclick="UI.save();UI.st.stack=[];UI.go('title',null,true)">🏠 Выйти в главное меню</button></div>
 <p class="sm mut ctr">Оригинальная игра в жанре «менеджер сборной». Все имена, клубы и данные вымышлены.</p>`; };
function slots(){ const m=meta(); modal(`<h2>Загрузить игру</h2>${[1,2,3].map(i=>m[i]?`<div class="row c" onclick="UI.loadFrom(${i})"><div class="f1"><div class="b">Слот ${i}</div><div class="sm mut">${(N.TEAMS.find(t=>t.c===m[i].t)||{f:''}).f} ${esc(m[i].c)} · ${N.fmtD(m[i].d,1)}</div></div>›</div>`:'').join('')}<button class="btn gh w" onclick="UI.closeM()">Отмена</button>`); }
function loadFrom(i){ closeM(); try{ if(load(i)){ toast('Игра загружена'); home(); } else toast('Слот пуст'); }catch(e){ modal('<h2>Не удалось загрузить</h2><div class="sm">'+esc(e.message)+'</div><div style="height:10px"></div><button class="btn gh w" onclick="UI.closeM()">OK</button>'); } }
function saveTo(i){ if(save(i)) toast('Сохранено в слот '+i); refresh(); }
function delSlot(i){ if(!confirm('Удалить сохранение в слоте '+i+'?'))return; localStorage.removeItem('nfm_s'+i); const m=meta(); delete m[i]; localStorage.setItem('nfm_meta',JSON.stringify(m)); refresh(); }
function exportSave(){ const blob=new Blob([N.serialize(S)],{type:'text/plain'}); const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='nfm_'+S.me+'_'+S.d+'.nfm'; a.click(); }
function importSave(inp){ const f=inp.files[0]; if(!f)return; f.text().then(t=>{ try{ const L=N.deserialize(t); oldCheck(L); S=L; N.setS(S); fixFlags(); S.slot=S.slot||1; save(); toast('Импортировано'); home(); }catch(e){ modal('<h2>Не удалось загрузить</h2><div class="sm">'+esc(e.message)+'</div><div style="height:10px"></div><button class="btn gh w" onclick="UI.closeM()">OK</button>'); } }); }
SCR.prematch=(fid)=>{ const f=S.F.find(x=>x.id===fid); if(!f||f.r)return home(); top('Перед матчем'); const opp=f.h===S.me?f.a:f.h; const o=T(opp);
 const n=S.u.call.length; const ok=n>=18&&n<=23; if(!N.validXI()) N.autoXI(S.u.xi&&S.u.xi.form);
 const os=N.setup(opp,f); const key=os.on.slice().sort((a,b)=>b.p.o-a.p.o).slice(0,3);
 const x=S.u.xi; const unavail=S.u.call.map(id=>S.P[id]).filter(p=>p&&(p.inj||p.sus));
 const h2h=S.F.filter(z=>z.u&&z.r&&(z.h===opp||z.a===opp)); const form=os.on.length?Math.round(os.on.reduce((s,e)=>s+e.p.o,0)/os.on.length):0;
 V().innerHTML=`<div class="card nm"><h3>${esc(cName(f))} · ${esc(f.st)}</h3><div class="vs"><div><div class="flag">${T(f.h).f}</div><div class="tn">${esc(T(f.h).n)}</div>${stars(T(f.h))}<div class="sm mut">Эло ${T(f.h).elo}</div></div><div class="b" style="font-size:22px">VS</div><div><div class="flag">${T(f.a).f}</div><div class="tn">${esc(T(f.a).n)}</div>${stars(T(f.a))}<div class="sm mut">Эло ${T(f.a).elo}</div></div></div><div class="ctr sm mut">${N.fmtD(f.d)} · ${f.neu?'нейтральное поле':f.h===S.me?'домашний матч':'выездной матч'}${koInfo(f)}</div>${venueInfo(f)}</div>
 <div class="card"><h3>Скаутский отчёт: ${esc(o.n)}</h3><div class="sm">Схема: <b>${o.form}</b> · средняя сила основы: <b>${form}</b><br>Ключевые игроки: ${key.map(e=>esc(e.p.n)+' ('+N.POS[e.p.pos][0]+', '+e.p.o+')').join(', ')}${h2h.length?`<br>Личные встречи при вас: ${h2h.map(z=>z.r.hg+':'+z.r.ag).join(', ')}`:''}</div></div>
 <div class="card"><h3>Наш состав · ${x.form}</h3>${x.s.map((id,i)=>{const p=S.P[id];const role=N.FORMS[x.form][i][0];return p?`<div class="row sm"><span class="pos p${N.POS[role][1]}">${N.POS[role][0]}</span><div class="f1">${esc(p.n)}${p.prom?' 🤝':''}</div><span class="${p.fit<75?'red':'mut'}">${Math.round(p.fit)}%</span><span class="ovr">${Math.round(N.roleOvr(p,role))}</span></div>`:''}).join('')}
 ${unavail.length?`<div class="sm red" style="margin-top:6px">Недоступны: ${unavail.map(p=>esc(short(p))+(p.inj?' 🚑':' 🟥')).join(', ')}</div>`:''}</div>
 ${ok?'':`<div class="card red">Вызов должен содержать 18–23 игрока (сейчас ${n}). <button class="btn sm" onclick="UI.autoCall()">Автовызов</button></div>`}
 <div class="grid2"><button class="btn" onclick="UI.go('squad')">👥 Вызов</button><button class="btn" onclick="UI.go('tactics')">📋 Тактика</button></div><div style="height:8px"></div>
 <button class="btn g w big" ${ok?'':'disabled'} onclick="UI.startMatch(${fid})">⚽ Начать матч</button><div style="height:6px"></div><button class="btn gh w" onclick="UI.quickMatch(${fid})" ${ok?'':'disabled'}>⏩ Быстрая симуляция</button>`; };
function koInfo(f){ if(!f.ko) return ''; if(f.leg===1) return ' · 1-й матч из двух (по сумме)'; if(f.leg===2){ const l=S.F.find(x=>x.id===f.l1); return ' · ответный матч: первый '+(l&&l.r?T(l.h).n+' '+l.r.hg+':'+l.r.ag+' '+T(l.a).n:'—')+'; при равенстве суммы — д.в. и пенальти (гол на выезде не учитывается)'; } return ' · плей-офф: при ничьей — д.в. и пенальти'; }
function venueInfo(f){ const v=N.venue(f); return `<div class="ctr sm mut">${N.WXN[v.wx]||''} · стадион на ${v.cap.toLocaleString('ru-RU')} мест · ожидается ${v.att.toLocaleString('ru-RU')} зрителей${f.neu?'':(v.fill>0.8?' · аншлаг, мощная поддержка хозяев':v.fill<0.45?' · полупустые трибуны':'')}</div>`; }
const SPD=[800,400,180,70];
function startMatch(fid,quick){ const f=S.F.find(x=>x.id===fid); const h=N.setup(f.h,f), a=N.setup(f.a,f); const side=f.h===S.me?0:1;
 const M=new N.Match(h,a,N.matchOpts(f)); st.m={M,f,side,spd:PREF.spd||0,paused:true,timer:null};
 if(quick){ M.o.autoUser=true; M.sim(); return endMatch(); }
 st.stack.push(['hub',null]); st.cur='match'; renderMatch(); setTimeout(()=>play(),600); }
function quickMatch(fid){ startMatch(fid,true); }
function renderMatch(){ const {M,f}=st.m; $('#top').innerHTML=`<div class="ttl">${esc(cName(f))}</div><div class="dt">${esc(f.st)}</div>`;
 const L='rgba(255,255,255,.4)';
 V().innerHTML=`<div class="sb"><div class="tm">${tf(f.h)}${esc(T(f.h).n)}</div><div class="ctr"><div class="sc" id="msc" style="transition:transform .3s">0:0</div><div class="mn" id="mmin">0'</div></div><div class="tm">${tf(f.a)}${esc(T(f.a).n)}</div></div>
 <div class="mpitch" id="mp"><div style="position:absolute;left:50%;top:0;bottom:0;border-left:2px solid ${L}"></div><div style="position:absolute;left:50%;top:50%;width:17%;aspect-ratio:1;transform:translate(-50%,-50%);border:2px solid ${L};border-radius:50%"></div><div style="position:absolute;left:0;top:22%;width:15.7%;height:56%;border:2px solid ${L};border-left:0"></div><div style="position:absolute;right:0;top:22%;width:15.7%;height:56%;border:2px solid ${L};border-right:0"></div><div style="position:absolute;left:0;top:40%;width:2%;height:20%;background:rgba(255,255,255,.5)"></div><div style="position:absolute;right:0;top:40%;width:2%;height:20%;background:rgba(255,255,255,.5)"></div><div class="ball" id="ball" style="left:50%;top:50%"></div></div>
 <div class="ctl"><button class="btn" id="bpp" onclick="UI.pp()">⏸</button><button class="btn" id="bsp" onclick="UI.spd()">×${[1,2,4,8][st.m.spd]}</button><button class="btn" onclick="UI.subsM()">🔁 Замены</button><button class="btn" onclick="UI.tacM()">📋 Тактика</button></div>
 <div class="card" style="padding:8px"><div class="sbar"><span class="v" id="pss0">50%</span><div class="tr"><i id="pssb" style="width:50%"></i></div><span class="v" id="pss1">50%</span></div><div class="sm ctr mut" id="mst"></div></div>
 <div class="card feed" id="feed"></div><button class="btn r w" onclick="UI.simEnd()">⏭ Досимулировать до конца</button>`;
 drawPlayers(); }
function drawPlayers(){ const {M}=st.m; const mp=$('#mp'); if(!mp)return; mp.querySelectorAll('.pl').forEach(e=>e.remove());
 for(const s of [0,1]) M.t[s].on.forEach((e,i)=>{ if(e.off)return; const d=document.createElement('div'); d.className='pl'; d.dataset.s=s; d.dataset.i=i; d.style.background=e.role==='GK'?(s===0?'#9cf':'#fc9'):(s===0?'#3d8bff':'#ff5a5f'); d.title=e.p.n; mp.appendChild(d); });
 posPlayers(); }
function roleXY(role,i,on){ const D={GK:[2,50],CB:[20,50],LB:[26,14],RB:[26,86],DM:[38,50],CM:[50,50],AM:[64,50],LM:[56,12],RM:[56,88],LW:[76,15],RW:[76,85],ST:[84,50]};
 const same=on.filter(e=>!e.off&&e.role===role); const k=same.indexOf(on[i]); const n=same.length; let [x,y]=D[role]; if(n>1&&['CB','CM','ST','DM','AM'].includes(role)){ y=50+(k-(n-1)/2)*(role==='CB'?20:22); } return [x,y]; }
function posPlayers(){ const {M}=st.m; const mp=$('#mp'); if(!mp)return; const bx=M.ball[0], by=M.ball[1];
 mp.querySelectorAll('.pl').forEach(d=>{ const s=+d.dataset.s,i=+d.dataset.i; const e=M.t[s].on[i]; if(!e)return; const [bxr,byr]=roleXY(e.role,i,M.t[s].on);
  const own = s===0?bx:100-bx; let x = e.role==='GK'? 3+Math.max(0,own-50)*0.06 : bxr*0.72+(own-38)*0.38+(M.possSide===s?4:-2);
  let y = byr+(by-50)*0.18; x=Math.max(1.5,Math.min(98.5,x)); if(s===1)x=100-x;
  d.style.left=(x+(Math.random()-.5)*2.5)+'%'; d.style.top=Math.max(3,Math.min(97,y+(Math.random()-.5)*4))+'%'; }); }
function play(){ const m=st.m; if(!m||m.M.done)return; m.paused=false; const b=$('#bpp'); if(b)b.textContent='⏸'; clearInterval(m.timer); m.timer=setInterval(tick,SPD[m.spd]); }
function pause(){ const m=st.m; if(!m)return; m.paused=true; clearInterval(m.timer); const b=$('#bpp'); if(b)b.textContent='▶'; }
function pp(){ st.m.paused?play():pause(); }
function spd(){ const m=st.m; m.spd=(m.spd+1)%4; $('#bsp').textContent='×'+[1,2,4,8][m.spd]; if(!m.paused)play(); }
function tick(){ const m=st.m; if(!m||st.cur!=='match'){ if(m)clearInterval(m.timer); return; } const M=m.M; const evs=M.step(); updateMatchUI(evs);
 if(evs.some(e=>e.t==='inj'&&e.side===m.side)){ pause(); toast('🚑 Травма! Сделайте замену'); subsM(); return; }
 if(evs.some(e=>e.t==='goal')){ const sb=$('#msc'); if(sb){sb.style.transform='scale(1.35)';setTimeout(()=>sb.style.transform='',450);} }
 if(evs.some(e=>e.t==='ht')&&!M.done){ pause(); toast(M.extra&&M.min>=90?'Дополнительное время':'Перерыв — можно изменить тактику'); setTimeout(()=>{ if(st.m===m&&m.paused&&$('#modal').classList.contains('hidden'))play(); },2200); }
 if(M.done){ clearInterval(m.timer); setTimeout(endMatch,1500); } }
function updateMatchUI(evs){ const m=st.m, M=m.M; const sc=$('#msc'); if(!sc)return; sc.textContent=M.score.join(':')+(M.pens?` (${M.pens.join(':')})`:''); $('#mmin').textContent=(M.done?'Конец':M.min+(M.inAdd&&M.addK?'+'+M.addK:'')+"'")+(M.extra&&!M.done?' ДВ':'');
 const ball=$('#ball'); const kf=M.kf||[[50,50]]; const dt=SPD[m.spd]/(kf.length+1); kf.forEach((k,i)=>setTimeout(()=>{ if(ball){ball.style.left=k[0]+'%';ball.style.top=k[1]+'%';} },dt*i));
 posPlayers(); const t=M.st[0].poss+M.st[1].poss||1; const p0=Math.round(M.st[0].poss/t*100); $('#pss0').textContent=p0+'%'; $('#pss1').textContent=(100-p0)+'%'; $('#pssb').style.width=p0+'%';
 $('#mst').innerHTML=`Удары ${M.st[0].sh}–${M.st[1].sh} · В створ ${M.st[0].sot}–${M.st[1].sot} · xG ${M.st[0].xg.toFixed(2)}–${M.st[1].xg.toFixed(2)} · Фолы ${M.st[0].fo}–${M.st[1].fo} · Угл. ${M.st[0].co}–${M.st[1].co}`;
 const feed=$('#feed'); for(const e of evs){ if(PREF.brief&&!['goal','yc','rc','sub','inj','ht','ft','kick','pk','var','add'].includes(e.t))continue; const d=document.createElement('div'); if(e.t==='goal')d.className='goal'; d.innerHTML=`<span class="m">${e.ml||e.m}'</span>${esc(e.txt)}`; feed.prepend(d); }
 while(feed.children.length>120)feed.lastChild.remove(); if(evs.some(e=>e.t==='sub'||e.t==='rc'))drawPlayers(); }
function simEnd(){ const m=st.m; pause(); const M=m.M; M.o.autoUser=true; const all=[]; while(!M.done) all.push(...M.step()); updateMatchUI(all.filter(e=>['goal','rc','ft','pk','sub'].includes(e.t))); setTimeout(endMatch,500); }
function subsM(){ const m=st.m, M=m.M, tm=M.t[m.side]; pause(); st.subSel={};
 const on=tm.on.filter(e=>!e.off); const bench=tm.bench.filter(p=>!M.ps[p.id]);
 modal(`<h2>Замены · осталось ${tm.subsLeft}</h2><div class="sm mut">Выберите игрока на поле (слева), затем запасного (справа).</div><div class="grid2"><div>${on.map(e=>{const P=M.ps[e.p.id];return `<div class="bp" style="margin:4px 0" id="so${e.p.id}" onclick="UI.subPick('o',${e.p.id})"><span class="pos p${N.POS[e.role][1]}">${N.POS[e.role][0]}</span>${esc(short(e.p))} <span class="${e.p._mfit<65?'red':'mut'}">${Math.round(e.p._mfit)}%</span>${e.inj?'🚑':''}${P.yc?'🟨':''}</div>`}).join('')}</div>
 <div>${bench.map(p=>`<div class="bp" style="margin:4px 0" id="si${p.id}" onclick="UI.subPick('i',${p.id})">${posB(p)}${esc(short(p))} <b>${p.o}</b></div>`).join('')||'<span class="mut sm">Нет запасных</span>'}</div></div>
 <div style="height:10px"></div><button class="btn g w" ${tm.subsLeft>0?'':'disabled'} onclick="UI.doSubBtn()">Произвести замену</button><div style="height:6px"></div><button class="btn gh w" onclick="UI.closeM();UI.play()">Продолжить матч</button>`); }
function subPick(k,id){ st.subSel[k]=id; document.querySelectorAll(`[id^=s${k}]`).forEach(e=>e.classList.remove('sel')); const el=$('#s'+k+id); if(el)el.classList.add('sel'); }
function doSubBtn(){ const m=st.m; const s=st.subSel||{}; if(!s.o||!s.i)return toast('Выберите обоих игроков'); if(m.M.doSub(m.side,s.o,s.i)){ const f=$('#feed'); const d=document.createElement('div'); d.innerHTML=`<span class="m">${m.M.min}'</span>`+esc(m.M.ev[m.M.ev.length-1].txt); f.prepend(d); drawPlayers(); subsM(); } else toast('Замена невозможна'); }
function tacM(){ const m=st.m; pause(); const tm=m.M.t[m.side]; modal(`<h2>Тактика по ходу матча</h2>${tacPanel(tm.tac,'UI.mTac')}<div class="sm mut">Схема</div><select onchange="UI.mForm(this.value)"><option value="">— оставить текущую —</option>${Object.keys(N.FORMS).map(f=>`<option>${f}</option>`).join('')}</select>
 <h3 class="sm mut" style="margin-top:10px">Индивидуальные установки</h3>${tm.on.filter(e=>!e.off&&e.role!=='GK').map(e=>`<div class="row sm"><span class="pos p${N.POS[e.role][1]}">${N.POS[e.role][0]}</span><div class="f1">${esc(short(e.p))}</div><select style="width:52%" onchange="UI.mInstr(${e.p.id},this.value)">${Object.entries(INSTR).map(([k,n])=>`<option value="${k}" ${(tm.instr[e.p.id]||'')===k?'selected':''}>${n}</option>`).join('')}</select></div>`).join('')}
 <div style="height:10px"></div><button class="btn g w" onclick="UI.closeM();UI.play()">Продолжить матч</button>`); }
function mTac(k,v){ const m=st.m; const tm=m.M.t[m.side]; tm.tac[k]=k==='style'?v:+v; m.M.calc(); }
function mInstr(id,k){ const m=st.m; const tm=m.M.t[m.side]; if(k)tm.instr[id]=k; else delete tm.instr[id]; m.M.calc(); }
function mForm(f){ if(!f)return; const m=st.m; const tm=m.M.t[m.side]; const F=N.FORMS[f]; const on=tm.on.filter(e=>!e.off); const used=new Set();
 const gk=on.find(e=>e.role==='GK'); if(gk)used.add(gk); for(const [role] of F){ if(role==='GK')continue; let best=null,bv=-1; for(const e of on){ if(used.has(e))continue; const v=N.roleOvr(e.p,role); if(v>bv){bv=v;best=e;} } if(best){used.add(best);best.role=role;} }
 m.M.calc(); drawPlayers(); toast('Схема изменена: '+f); }
function endMatch(){ const m=st.m; if(!m||m.ended)return; m.ended=1; clearInterval(m.timer); closeM(); N.playFix(m.f,m.M); save(); st.cur='post'; st.stack=[]; SCR.post(); window.scrollTo(0,0); }
SCR.post=()=>{ const m=st.m, f=m.f, r=f.r; top('Итоги матча',false); const my=m.side===0?r.hg:r.ag, op=m.side===0?r.ag:r.hg; const w=r.w&&!r.agg?(r.w===S.me):my>op; const lost=r.w&&!r.agg?(r.w!==S.me):my<op;
 V().innerHTML=`<div class="card ctr nm"><div style="font-size:40px">${w?'🎉':lost?'😞':'🤝'}</div><div class="b" style="font-size:20px">${w?'Победа!':lost?'Поражение':'Ничья'}</div><div class="sm mut">${esc(cName(f))} · ${esc(f.st)}</div></div>
 <div class="sb"><div class="tm">${tf(f.h)}${esc(T(f.h).n)}</div><div class="ctr"><div class="sc">${r.hg}:${r.ag}</div><div class="mn">${r.pen?'пен. '+r.pen.join(':'):r.et?'д.в.':''}${r.agg?' сумма '+r.agg[0]+':'+r.agg[1]:''}</div></div><div class="tm">${tf(f.a)}${esc(T(f.a).n)}</div></div>
 ${r.agg?`<div class="card ctr b ${r.w===S.me?'grn':'red'}">${r.w===S.me?'Проходим дальше по сумме двух матчей!':'Выбываем по сумме двух матчей.'}</div>`:''}<div class="card">${r.det.ev.filter(e=>e[1]==='goal'||e[1]==='rc'||e[1]==='inj'||e[1]==='var').map(e=>`<div class="sm"><b class="gold">${e[0]}'</b> ${esc(e[3])}</div>`).join('')||'<div class="sm mut ctr">Без голов</div>'}</div>
 ${ratingsHTML(r.det.ps,f)}${statsHTML(r.det.st)}
 <div class="sm ctr mut">Доверие федерации: ${S.u.trust}%</div><div style="height:8px"></div><button class="btn g w big" onclick="UI.afterPost()">Продолжить</button>`; };
function afterPost(){ st.m=null; if(S.u.press) return pressConf(); if(S.u.fired) return go('fired',null,true); home(); }
function pressConf(){ const p=S.u.press; st.pq=0; st.lockM=true; st.pshow=()=>{ const q=p.Q[st.pq]; modal(`<div class="sm mut">🎤 Пресс-конференция · ${esc(p.c)} · вопрос ${st.pq+1}/${p.Q.length}</div><h2 style="margin:8px 0">«${esc(q.q)}»</h2>${q.a.map((a,i)=>`<div class="row c" onclick="UI.pressAns(${i})"><span>💬</span><div class="f1">${esc(a[0])}</div></div>`).join('')}`); }; st.pshow(); }
function pressAns(i){ const p=S.u.press; const q=p.Q[st.pq]; N.applyPress(q.a[i][1]); st.pq++; if(st.pq<p.Q.length) return st.pshow(); S.u.press=null; st.lockM=false; closeM(); save(); toast('Пресс-конференция завершена'); if(S.u.fired) return go('fired',null,true); home(); }
function refresh(){ if(st.cur&&SCR[st.cur]&&st.cur!=='match'&&st.cur!=='post'){ const y=window.scrollY; SCR[st.cur](st.arg); window.scrollTo(0,y); } }
window.UI={go,back,home,st,S:()=>S,PREF,savePref,save,closeM,refresh,cont,help,pickTeam,start,openMail,acceptJob,takeJ,toggleCall,autoCall,doScout,invite,player,talk,setForm,autoXIbtn,setTac,setInstr,upg,friendly,doFriendly,matchDet,slots,loadFrom,saveTo,delSlot,exportSave,importSave,startMatch,quickMatch,pp,spd,play,subsM,subPick,doSubBtn,tacM,mTac,mInstr,mForm,simEnd,afterPost,pressAns};
go('title',null,true);
})();
